<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('Assign') }} {{ $t(TabsArray.find(t => t.displayCode === "PROJECT_TEAM")?.displayName || 'Team')}}</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default{
    props:{
        BacklogId:{
            type:Number,
            Required:true
        },
        AssigenedUser:{
            type:String,
            Required:true
        },
        NewTabName:{
            type:String,
            require: true
        },
        AssignTabTabName:{
            type:String,
            require: true
        },
        AssignSprintTab:{
            type:String,
            require: true
        },
        TabsArray: {
            type: Array
        },
    },
    data(){
        return{
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            isLoading:false,
            FormSchema: [               
                {
                    layoutType: "double",
                    Data: [                       
                        {
                            astype: "MultiSelectField",                                                
                            label: this.$t('Assign'),
                            name: "AssignUser",
                            mode: "tag",
                            multiple:false,
                            value: "", 
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select') + " " + this.$t(this.TabsArray.find(t => t.displayCode === "PROJECT_TEAM")?.displayName || 'Team'),
                            validationRules: { "required": true, max: 100 },
                        }                       
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true   
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Close,
                },
            ],
            TeamMemberData:[],
            ProjectId:0
        }
    },
    created:async function(){  
        var ths= this;  
        ths.ProjectId = parseInt(ths.$route.params.projectId); 
        ths.FormSchema[0].Data[0].label=`${this.$t('Select')} ${ths.$t(ths.TabsArray.find(t => t.displayCode === "PROJECT_TEAM")?.displayName || 'Team')}`;        
        ths.GetUsers();            
    },
    methods:{
        GetUsers(){
            var vm=this;       
            var url = `id=${vm.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {                            
                            vm.TeamMemberData=response.data.DATA;
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    value: element.value,
                                    name: element.name
                                }
                                vm.FormSchema[0].Data[0].config.options.push(obj);
                            })
                        }
                        else {
                            vm.$refs.AssignTagForm.UpdateKeyValue();
                        }
                        if(vm.AssigenedUser != null){
                            vm.BindAssigenedUsers();
                        } 
                    }
                }
            });            
        }, 
        BindAssigenedUsers(){
            var vm =this;
            const userIdArray = vm.AssigenedUser.split(',').map(id => parseInt(id, 10));
            const filteredData= vm.TeamMemberData.filter(member => userIdArray.includes(parseInt(member.value, 10)));
            var UserData=[];
            filteredData.forEach((element)=>{
                let obj={
                    value:element.value,
                    label:element.name
                }
                UserData.push(obj);                        
            })
            vm.FormSchema[0].Data[0].value=UserData; 
        },       
        OnSubmit:async function(){            
            var ths=this;
            ths.isLoading=true;
            var val = "";           
            ths.FormSchema[0].Data[0].value.forEach((itm)=>{                               
                val += itm.value;
                val += ',';
            });
            var VarObject = {
                BacklogId:ths.BacklogId,
                ProjectId: ths.$route.params.projectId,
                UserId: val
            }    
            var objectPostString = JSON.stringify(VarObject);
            await DataService.UpdateAssignUser(objectPostString).then(function (response) {
                ths.isLoading=false;
                if(response.data.result.DATA.length>0){ 
                    ths.ShowAlert(ths.$t('AddedSuccess',[ths.$t(ths.TabsArray.find(t => t.displayCode === "PROJECT_TEAM")?.displayName || 'Team')]),"success", true, ths.$t("Alert"));
                    ths.$emit('CallbackFunction');
                    ths.Close();
                }else{
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            })
        },
        Close:function(){
            var vm = this;
            vm.$parent.IsAssignedUser=false;
        }
    }
}
</script>